/// <summary>
/// PricingAttribute of table <c>InventItemLocation</c> field WMSLocationIdDefaultReceipt.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventItemLocationWMSLocationIdDefaultReceipt extends UPSPricingAttributeInventItemLocation implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventItemLocation, WMSLocationIdDefaultReceipt);
}

public Set getAllowedValues()
{
    var                ret = new Set(Types::String);
    InventItemLocation inventItemLocation;

    while select inventItemLocation
        group by WMSLocationIdDefaultReceipt
    {
        if (! ret.in(inventItemLocation.WMSLocationIdDefaultReceipt))
        {
            ret.add(inventItemLocation.WMSLocationIdDefaultReceipt);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventItemLocation, WMSLocationIdDefaultReceipt));
    qbr.value(queryValue(_value));
}
